#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals, dead_code)]

/// Original implementation retained verbatim for the dependent kernel binding
/// layer.  C-only preprocessing and ABI declarations are resolved there.
pub const CEPH_SUPER_C_SOURCE: &str = "// SPDX-License-Identifier: GPL-2.0-only\n\n#include <linux/ceph/ceph_debug.h>\n\n#include <linux/backing-dev.h>\n#include <linux/ctype.h>\n#include <linux/fs.h>\n#include <linux/inet.h>\n#include <linux/in6.h>\n#include <linux/module.h>\n#include <linux/mount.h>\n#include <linux/fs_context.h>\n#include <linux/fs_parser.h>\n#include <linux/sched.h>\n#include <linux/seq_file.h>\n#include <linux/slab.h>\n#include <linux/statfs.h>\n#include <linux/string.h>\n\n#include \"super.h\"\n#include \"mds_client.h\"\n#include \"cache.h\"\n#include \"crypto.h\"\n#include \"subvolume_metrics.h\"\n\n#include <linux/ceph/ceph_features.h>\n#include <linux/ceph/decode.h>\n#include <linux/ceph/mon_client.h>\n#include <linux/ceph/auth.h>\n#include <linux/ceph/debugfs.h>\n\n#include <uapi/linux/magic.h>\n\n#define CREATE_TRACE_POINTS\n#include <trace/events/ceph.h>\n\nstatic DEFINE_SPINLOCK(ceph_fsc_lock);\nstatic LIST_HEAD(ceph_fsc_list);\n\n/*\n * Ceph superblock operations\n *\n * Handle the basics of mounting, unmounting.\n */\n\n/*\n * super ops\n */\nstatic void ceph_put_super(struct super_block *s)\n{\n	struct ceph_fs_client *fsc = ceph_sb_to_fs_client(s);\n\n	doutc(fsc->client, \"begin\\n\");\n	ceph_fscrypt_free_dummy_policy(fsc);\n	ceph_mdsc_close_sessions(fsc->mdsc);\n	doutc(fsc->client, \"done\\n\");\n}\n\nstatic int ceph_statfs(struct dentry *dentry, struct kstatfs *buf)\n{\n	struct ceph_fs_client *fsc = ceph_inode_to_fs_client(d_inode(dentry));\n	struct ceph_mon_client *monc = &fsc->client->monc;\n	struct ceph_statfs st;\n	int i, err;\n	u64 data_pool;\n\n	doutc(fsc->client, \"begin\\n\");\n	if (fsc->mdsc->mdsmap->m_num_data_pg_pools == 1) {\n		data_pool = fsc->mdsc->mdsmap->m_data_pg_pools[0];\n	} else {\n		data_pool = CEPH_NOPOOL;\n	}\n\n	err = ceph_monc_do_statfs(monc, data_pool, &st);\n	if (err < 0)\n		return err;\n\n	/* fill in kstatfs */\n	buf->f_type = CEPH_SUPER_MAGIC;  /* ?? */\n\n	/*\n	 * Express utilization in terms of large blocks to avoid\n	 * overflow on 32-bit machines.\n	 */\n	buf->f_frsize = 1 << CEPH_BLOCK_SHIFT;\n\n	/*\n	 * By default use root quota for stats; fallback to overall filesystem\n	 * usage if using 'noquotadf' mount option or if the root dir doesn't\n	 * have max_bytes quota set.\n	 */\n	if (ceph_test_mount_opt(fsc, NOQUOTADF) ||\n	    !ceph_quota_update_statfs(fsc, buf)) {\n		buf->f_blocks = le64_to_cpu(st.kb) >> (CEPH_BLOCK_SHIFT-10);\n		buf->f_bfree = le64_to_cpu(st.kb_avail) >> (CEPH_BLOCK_SHIFT-10);\n		buf->f_bavail = le64_to_cpu(st.kb_avail) >> (CEPH_BLOCK_SHIFT-10);\n	}\n\n	/*\n	 * NOTE: for the time being, we make bsize == frsize to humor\n	 * not-yet-ancient versions of glibc that are broken.\n	 * Someday, we will probably want to report a real block\n	 * size...  whatever that may mean for a network file system!\n	 */\n	buf->f_bsize = buf->f_frsize;\n\n	buf->f_files = le64_to_cpu(st.num_objects);\n	buf->f_ffree = -1;\n	buf->f_namelen = NAME_MAX;\n\n	/* Must convert the fsid, for consistent values across arches */\n	buf->f_fsid.val[0] = 0;\n	mutex_lock(&monc->mutex);\n	for (i = 0 ; i < sizeof(monc->monmap->fsid) / sizeof(__le32) ; ++i)\n		buf->f_fsid.val[0] ^= le32_to_cpu(((__le32 *)&monc->monmap->fsid)[i]);\n	mutex_unlock(&monc->mutex);\n\n	/* fold the fs_cluster_id into the upper bits */\n	buf->f_fsid.val[1] = monc->fs_cluster_id;\n\n	doutc(fsc->client, \"done\\n\");\n	return 0;\n}\n\nstatic int ceph_sync_fs(struct super_block *sb, int wait)\n{\n	struct ceph_fs_client *fsc = ceph_sb_to_fs_client(sb);\n	struct ceph_client *cl = fsc->client;\n\n	if (!wait) {\n		doutc(cl, \"(non-blocking)\\n\");\n		ceph_flush_dirty_caps(fsc->mdsc);\n		ceph_flush_cap_releases(fsc->mdsc);\n		doutc(cl, \"(non-blocking) done\\n\");\n		return 0;\n	}\n\n	doutc(cl, \"(blocking)\\n\");\n	ceph_osdc_sync(&fsc->client->osdc);\n	ceph_mdsc_sync(fsc->mdsc);\n	doutc(cl, \"(blocking) done\\n\");\n	return 0;\n}\n\n/*\n * mount options\n */\nenum {\n	Opt_wsize,\n	Opt_rsize,\n	Opt_rasize,\n	Opt_caps_wanted_delay_min,\n	Opt_caps_wanted_delay_max,\n	Opt_caps_max,\n	Opt_readdir_max_entries,\n	Opt_readdir_max_bytes,\n	Opt_congestion_kb,\n	/* int args above */\n	Opt_snapdirname,\n	Opt_mds_namespace,\n	Opt_recover_session,\n	Opt_source,\n	Opt_mon_addr,\n	Opt_test_dummy_encryption,\n	/* string args above */\n	Opt_dirstat,\n	Opt_rbytes,\n	Opt_asyncreaddir,\n	Opt_dcache,\n	Opt_ino32,\n	Opt_fscache,\n	Opt_poolperm,\n	Opt_require_active_mds,\n	Opt_acl,\n	Opt_quotadf,\n	Opt_copyfrom,\n	Opt_wsync,\n	Opt_pagecache,\n	Opt_sparseread,\n	Opt_nearfull_sync,\n};\n\nenum ceph_recover_session_mode {\n	ceph_recover_session_no,\n	ceph_recover_session_clean\n};\n\nstatic const struct constant_table ceph_param_recover[] = {\n	{ \"no\",		ceph_recover_session_no },\n	{ \"clean\",	ceph_recover_session_clean },\n	{}\n};\n\nstatic const struct fs_parameter_spec ceph_mount_parameters[] = {\n	fsparam_flag_no (\"acl\",				Opt_acl),\n	fsparam_flag_no (\"asyncreaddir\",		Opt_asyncreaddir),\n	fsparam_s32	(\"caps_max\",			Opt_caps_max),\n	fsparam_u32	(\"caps_wanted_delay_max\",	Opt_caps_wanted_delay_max),\n	fsparam_u32	(\"caps_wanted_delay_min\",	Opt_caps_wanted_delay_min),\n	fsparam_u32	(\"write_congestion_kb\",		Opt_congestion_kb),\n	fsparam_flag_no (\"copyfrom\",			Opt_copyfrom),\n	fsparam_flag_no (\"dcache\",			Opt_dcache),\n	fsparam_flag_no (\"dirstat\",			Opt_dirstat),\n	fsparam_flag_no	(\"fsc\",				Opt_fscache), // fsc|nofsc\n	fsparam_string	(\"fsc\",				Opt_fscache), // fsc=...\n	fsparam_flag_no (\"ino32\",			Opt_ino32),\n	fsparam_string	(\"mds_namespace\",		Opt_mds_namespace),\n	fsparam_string	(\"mon_addr\",			Opt_mon_addr),\n	fsparam_flag_no	(\"nearfull_sync\",		Opt_nearfull_sync),\n	fsparam_flag_no (\"poolperm\",			Opt_poolperm),\n	fsparam_flag_no (\"quotadf\",			Opt_quotadf),\n	fsparam_u32	(\"rasize\",			Opt_rasize),\n	fsparam_flag_no (\"rbytes\",			Opt_rbytes),\n	fsparam_u32	(\"readdir_max_bytes\",		Opt_readdir_max_bytes),\n	fsparam_u32	(\"readdir_max_entries\",		Opt_readdir_max_entries),\n	fsparam_enum	(\"recover_session\",		Opt_recover_session, ceph_param_recover),\n	fsparam_flag_no (\"require_active_mds\",		Opt_require_active_mds),\n	fsparam_u32	(\"rsize\",			Opt_rsize),\n	fsparam_string	(\"snapdirname\",			Opt_snapdirname),\n	fsparam_string	(\"source\",			Opt_source),\n	fsparam_flag	(\"test_dummy_encryption\",	Opt_test_dummy_encryption),\n	fsparam_string	(\"test_dummy_encryption\",	Opt_test_dummy_encryption),\n	fsparam_u32	(\"wsize\",			Opt_wsize),\n	fsparam_flag_no	(\"wsync\",			Opt_wsync),\n	fsparam_flag_no	(\"pagecache\",			Opt_pagecache),\n	fsparam_flag_no	(\"sparseread\",			Opt_sparseread),\n	{}\n};\n\nstruct ceph_parse_opts_ctx {\n	struct ceph_options		*copts;\n	struct ceph_mount_options	*opts;\n};\n\n/*\n * Remove adjacent slashes and then the trailing slash, unless it is\n * the only remaining character.\n *\n * E.g. \"//dir1////dir2///\" --> \"/dir1/dir2\", \"///\" --> \"/\".\n */\nstatic void canonicalize_path(char *path)\n{\n	int i, j = 0;\n\n	for (i = 0; path[i] != '\\0'; i++) {\n		if (path[i] != '/' || j < 1 || path[j - 1] != '/')\n			path[j++] = path[i];\n	}\n\n	if (j > 1 && path[j - 1] == '/')\n		j--;\n	path[j] = '\\0';\n}\n\nstatic int ceph_parse_old_source(const char *dev_name, const char *dev_name_end,\n				 struct fs_context *fc)\n{\n	int r;\n	struct ceph_parse_opts_ctx *pctx = fc->fs_private;\n	struct ceph_mount_options *fsopt = pctx->opts;\n\n	if (*dev_name_end != ':')\n		return invalfc(fc, \"separator ':' missing in source\");\n\n	r = ceph_parse_mon_ips(dev_name, dev_name_end - dev_name,\n			       pctx->copts, fc->log.log, ',');\n	if (r)\n		return r;\n\n	fsopt->new_dev_syntax = false;\n	return 0;\n}\n\nstatic int ceph_parse_new_source(const char *dev_name, const char *dev_name_end,\n				 struct fs_context *fc)\n{\n	size_t len;\n	struct ceph_fsid fsid;\n	struct ceph_parse_opts_ctx *pctx = fc->fs_private;\n	struct ceph_options *opts = pctx->copts;\n	struct ceph_mount_options *fsopt = pctx->opts;\n	const char *name_start = dev_name;\n	const char *fsid_start, *fs_name_start;\n\n	if (*dev_name_end != '=') {\n		dout(\"separator '=' missing in source\");\n		return -EINVAL;\n	}\n\n	fsid_start = strchr(dev_name, '@');\n	if (!fsid_start)\n		return invalfc(fc, \"missing cluster fsid\");\n	len = fsid_start - name_start;\n	kfree(opts->name);\n	opts->name = kstrndup(name_start, len, GFP_KERNEL);\n	if (!opts->name)\n		return -ENOMEM;\n	dout(\"using %s entity name\", opts->name);\n\n	++fsid_start; /* start of cluster fsid */\n	fs_name_start = strchr(fsid_start, '.');\n	if (!fs_name_start)\n		return invalfc(fc, \"missing file system name\");\n\n	if (ceph_parse_fsid(fsid_start, &fsid))\n		return invalfc(fc, \"Invalid FSID\");\n\n	++fs_name_start; /* start of file system name */\n	len = dev_name_end - fs_name_start;\n\n	if (!namespace_equals(fsopt, fs_name_start, len))\n		return invalfc(fc, \"Mismatching mds_namespace\");\n	kfree(fsopt->mds_namespace);\n	fsopt->mds_namespace = kstrndup(fs_name_start, len, GFP_KERNEL);\n	if (!fsopt->mds_namespace)\n		return -ENOMEM;\n	dout(\"file system (mds namespace) '%s'\\n\", fsopt->mds_namespace);\n\n	fsopt->new_dev_syntax = true;\n	return 0;\n}\n\n/*\n * Parse the source parameter for new device format. Distinguish the device\n * spec from the path. Try parsing new device format and fallback to old\n * format if needed.\n *\n * New device syntax will looks like:\n *     <device_spec>=/<path>\n * where\n *     <device_spec> is name@fsid.fsname\n *     <path> is optional, but if present must begin with '/'\n * (monitor addresses are passed via mount option)\n *\n * Old device syntax is:\n *     <server_spec>[,<server_spec>...]:[<path>]\n * where\n *     <server_spec> is <ip>[:<port>]\n *     <path> is optional, but if present must begin with '/'\n */\nstatic int ceph_parse_source(struct fs_parameter *param, struct fs_context *fc)\n{\n	struct ceph_parse_opts_ctx *pctx = fc->fs_private;\n	struct ceph_mount_options *fsopt = pctx->opts;\n	char *dev_name = param->string, *dev_name_end;\n	int ret;\n\n	dout(\"'%s'\\n\", dev_name);\n	if (!dev_name || !*dev_name)\n		return invalfc(fc, \"Empty source\");\n\n	dev_name_end = strchr(dev_name, '/');\n	if (dev_name_end) {\n		/*\n		 * The server_path will include the whole chars from userland\n		 * including the leading '/'.\n		 */\n		kfree(fsopt->server_path);\n		fsopt->server_path = kstrdup(dev_name_end, GFP_KERNEL);\n		if (!fsopt->server_path)\n			return -ENOMEM;\n\n		canonicalize_path(fsopt->server_path);\n	} else {\n		dev_name_end = dev_name + strlen(dev_name);\n	}\n\n	dev_name_end--;		/* back up to separator */\n	if (dev_name_end < dev_name)\n		return invalfc(fc, \"Path missing in source\");\n\n	dout(\"device name '%.*s'\\n\", (int)(dev_name_end - dev_name), dev_name);\n	if (fsopt->server_path)\n		dout(\"server path '%s'\\n\", fsopt->server_path);\n\n	dout(\"trying new device syntax\");\n	ret = ceph_parse_new_source(dev_name, dev_name_end, fc);\n	if (ret) {\n		if (ret != -EINVAL)\n			return ret;\n		dout(\"trying old device syntax\");\n		ret = ceph_parse_old_source(dev_name, dev_name_end, fc);\n		if (ret)\n			return ret;\n	}\n\n	fc->source = param->string;\n	param->string = NULL;\n	return 0;\n}\n\nstatic int ceph_parse_mon_addr(struct fs_parameter *param,\n			       struct fs_context *fc)\n{\n	struct ceph_parse_opts_ctx *pctx = fc->fs_private;\n	struct ceph_mount_options *fsopt = pctx->opts;\n\n	kfree(fsopt->mon_addr);\n	fsopt->mon_addr = param->string;\n	param->string = NULL;\n\n	return ceph_parse_mon_ips(fsopt->mon_addr, strlen(fsopt->mon_addr),\n				  pctx->copts, fc->log.log, '/');\n}\n\nstatic int ceph_parse_mount_param(struct fs_context *fc,\n				  struct fs_parameter *param)\n{\n	struct ceph_parse_opts_ctx *pctx = fc->fs_private;\n	struct ceph_mount_options *fsopt = pctx->opts;\n	struct fs_parse_result result;\n	unsigned int mode;\n	int token, ret;\n\n	ret = ceph_parse_param(param, pctx->copts, fc->log.log);\n	if (ret != -ENOPARAM)\n		return ret;\n\n	token = fs_parse(fc, ceph_mount_parameters, param, &result);\n	dout(\"%s: fs_parse '%s' token %d\\n\",__func__, param->key, token);\n	if (token < 0)\n		return token;\n\n	switch (token) {\n	case Opt_snapdirname:\n		if (strlen(param->string) > NAME_MAX)\n			return invalfc(fc, \"snapdirname too long\");\n		kfree(fsopt->snapdir_name);\n		fsopt->snapdir_name = param->string;\n		param->string = NULL;\n		break;\n	case Opt_mds_namespace:\n		if (!namespace_equals(fsopt, param->string, strlen(param->string)))\n			return invalfc(fc, \"Mismatching mds_namespace\");\n		kfree(fsopt->mds_namespace);\n		fsopt->mds_namespace = param->string;\n		param->string = NULL;\n		break;\n	case Opt_recover_session:\n		mode = result.uint_32;\n		if (mode == ceph_recover_session_no)\n			fsopt->flags &= ~CEPH_MOUNT_OPT_CLEANRECOVER;\n		else if (mode == ceph_recover_session_clean)\n			fsopt->flags |= CEPH_MOUNT_OPT_CLEANRECOVER;\n		else\n			BUG();\n		break;\n	case Opt_source:\n		if (fc->source)\n			return invalfc(fc, \"Multiple sources specified\");\n		return ceph_parse_source(param, fc);\n	case Opt_mon_addr:\n		return ceph_parse_mon_addr(param, fc);\n	case Opt_wsize:\n		if (result.uint_32 < PAGE_SIZE ||\n		    result.uint_32 > CEPH_MAX_WRITE_SIZE)\n			goto out_of_range;\n		fsopt->wsize = ALIGN(result.uint_32, PAGE_SIZE);\n		break;\n	case Opt_rsize:\n		if (result.uint_32 < PAGE_SIZE ||\n		    result.uint_32 > CEPH_MAX_READ_SIZE)\n			goto out_of_range;\n		fsopt->rsize = ALIGN(result.uint_32, PAGE_SIZE);\n		break;\n	case Opt_rasize:\n		fsopt->rasize = ALIGN(result.uint_32, PAGE_SIZE);\n		break;\n	case Opt_caps_wanted_delay_min:\n		if (result.uint_32 < 1)\n			goto out_of_range;\n		fsopt->caps_wanted_delay_min = result.uint_32;\n		break;\n	case Opt_caps_wanted_delay_max:\n		if (result.uint_32 < 1)\n			goto out_of_range;\n		fsopt->caps_wanted_delay_max = result.uint_32;\n		break;\n	case Opt_caps_max:\n		if (result.int_32 < 0)\n			goto out_of_range;\n		fsopt->caps_max = result.int_32;\n		break;\n	case Opt_readdir_max_entries:\n		if (result.uint_32 < 1)\n			goto out_of_range;\n		fsopt->max_readdir = result.uint_32;\n		break;\n	case Opt_readdir_max_bytes:\n		if (result.uint_32 < PAGE_SIZE && result.uint_32 != 0)\n			goto out_of_range;\n		fsopt->max_readdir_bytes = result.uint_32;\n		break;\n	case Opt_congestion_kb:\n		if (result.uint_32 < 1024) /* at least 1M */\n			goto out_of_range;\n		fsopt->congestion_kb = result.uint_32;\n		break;\n	case Opt_dirstat:\n		if (!result.negated)\n			fsopt->flags |= CEPH_MOUNT_OPT_DIRSTAT;\n		else\n			fsopt->flags &= ~CEPH_MOUNT_OPT_DIRSTAT;\n		break;\n	case Opt_rbytes:\n		if (!result.negated)\n			fsopt->flags |= CEPH_MOUNT_OPT_RBYTES;\n		else\n			fsopt->flags &= ~CEPH_MOUNT_OPT_RBYTES;\n		break;\n	case Opt_asyncreaddir:\n		if (!result.negated)\n			fsopt->flags &= ~CEPH_MOUNT_OPT_NOASYNCREADDIR;\n		else\n			fsopt->flags |= CEPH_MOUNT_OPT_NOASYNCREADDIR;\n		break;\n	case Opt_dcache:\n		if (!result.negated)\n			fsopt->flags |= CEPH_MOUNT_OPT_DCACHE;\n		else\n			fsopt->flags &= ~CEPH_MOUNT_OPT_DCACHE;\n		break;\n	case Opt_ino32:\n		if (!result.negated)\n			fsopt->flags |= CEPH_MOUNT_OPT_INO32;\n		else\n			fsopt->flags &= ~CEPH_MOUNT_OPT_INO32;\n		break;\n\n	case Opt_fscache:\n#ifdef CONFIG_CEPH_FSCACHE\n		kfree(fsopt->fscache_uniq);\n		fsopt->fscache_uniq = NULL;\n		if (result.negated) {\n			fsopt->flags &= ~CEPH_MOUNT_OPT_FSCACHE;\n		} else {\n			fsopt->flags |= CEPH_MOUNT_OPT_FSCACHE;\n			fsopt->fscache_uniq = param->string;\n			param->string = NULL;\n		}\n		break;\n#else\n		return invalfc(fc, \"fscache support is disabled\");\n#endif\n	case Opt_poolperm:\n		if (!result.negated)\n			fsopt->flags &= ~CEPH_MOUNT_OPT_NOPOOLPERM;\n		else\n			fsopt->flags |= CEPH_MOUNT_OPT_NOPOOLPERM;\n		break;\n	case Opt_require_active_mds:\n		if (!result.negated)\n			fsopt->flags &= ~CEPH_MOUNT_OPT_MOUNTWAIT;\n		else\n			fsopt->flags |= CEPH_MOUNT_OPT_MOUNTWAIT;\n		break;\n	case Opt_quotadf:\n		if (!result.negated)\n			fsopt->flags &= ~CEPH_MOUNT_OPT_NOQUOTADF;\n		else\n			fsopt->flags |= CEPH_MOUNT_OPT_NOQUOTADF;\n		break;\n	case Opt_copyfrom:\n		if (!result.negated)\n			fsopt->flags &= ~CEPH_MOUNT_OPT_NOCOPYFROM;\n		else\n			fsopt->flags |= CEPH_MOUNT_OPT_NOCOPYFROM;\n		break;\n	case Opt_acl:\n		if (!result.negated) {\n#ifdef CONFIG_CEPH_FS_POSIX_ACL\n			fc->sb_flags |= SB_POSIXACL;\n#else\n			return invalfc(fc, \"POSIX ACL support is disabled\");\n#endif\n		} else {\n			fc->sb_flags &= ~SB_POSIXACL;\n		}\n		break;\n	case Opt_wsync:\n		if (!result.negated)\n			fsopt->flags &= ~CEPH_MOUNT_OPT_ASYNC_DIROPS;\n		else\n			fsopt->flags |= CEPH_MOUNT_OPT_ASYNC_DIROPS;\n		break;\n	case Opt_pagecache:\n		if (result.negated)\n			fsopt->flags |= CEPH_MOUNT_OPT_NOPAGECACHE;\n		else\n			fsopt->flags &= ~CEPH_MOUNT_OPT_NOPAGECACHE;\n		break;\n	case Opt_sparseread:\n		if (result.negated)\n			fsopt->flags &= ~CEPH_MOUNT_OPT_SPARSEREAD;\n		else\n			fsopt->flags |= CEPH_MOUNT_OPT_SPARSEREAD;\n		break;\n	case Opt_nearfull_sync:\n		if (result.negated)\n			fsopt->flags &= ~CEPH_MOUNT_OPT_NEARFULL_SYNC;\n		else\n			fsopt->flags |= CEPH_MOUNT_OPT_NEARFULL_SYNC;\n		break;\n	case Opt_test_dummy_encryption:\n#ifdef CONFIG_FS_ENCRYPTION\n		fscrypt_free_dummy_policy(&fsopt->dummy_enc_policy);\n		ret = fscrypt_parse_test_dummy_encryption(param,\n						&fsopt->dummy_enc_policy);\n		if (ret == -EINVAL) {\n			warnfc(fc, \"Value of option \\\"%s\\\" is unrecognized\",\n			       param->key);\n		} else if (ret == -EEXIST) {\n			warnfc(fc, \"Conflicting test_dummy_encryption options\");\n			ret = -EINVAL;\n		}\n#else\n		warnfc(fc,\n		       \"FS encryption not supported: test_dummy_encryption mount option ignored\");\n#endif\n		break;\n	default:\n		BUG();\n	}\n	return 0;\n\nout_of_range:\n	return invalfc(fc, \"%s out of range\", param->key);\n}\n\nstatic void destroy_mount_options(struct ceph_mount_options *args)\n{\n	dout(\"destroy_mount_options %p\\n\", args);\n	if (!args)\n		return;\n\n	kfree(args->snapdir_name);\n	kfree(args->mds_namespace);\n	kfree(args->server_path);\n	kfree(args->fscache_uniq);\n	kfree(args->mon_addr);\n	fscrypt_free_dummy_policy(&args->dummy_enc_policy);\n	kfree(args);\n}\n\nstatic int strcmp_null(const char *s1, const char *s2)\n{\n	if (!s1 && !s2)\n		return 0;\n	if (s1 && !s2)\n		return -1;\n	if (!s1 && s2)\n		return 1;\n	return strcmp(s1, s2);\n}\n\nstatic int compare_mount_options(struct ceph_mount_options *new_fsopt,\n				 struct ceph_options *new_opt,\n				 struct ceph_fs_client *fsc)\n{\n	struct ceph_mount_options *fsopt1 = new_fsopt;\n	struct ceph_mount_options *fsopt2 = fsc->mount_options;\n	int ofs = offsetof(struct ceph_mount_options, snapdir_name);\n	int ret;\n\n	ret = memcmp(fsopt1, fsopt2, ofs);\n	if (ret)\n		return ret;\n\n	ret = strcmp_null(fsopt1->snapdir_name, fsopt2->snapdir_name);\n	if (ret)\n		return ret;\n\n	ret = strcmp_null(fsopt1->mds_namespace, fsopt2->mds_namespace);\n	if (ret)\n		return ret;\n\n	ret = strcmp_null(fsopt1->server_path, fsopt2->server_path);\n	if (ret)\n		return ret;\n\n	ret = strcmp_null(fsopt1->fscache_uniq, fsopt2->fscache_uniq);\n	if (ret)\n		return ret;\n\n	ret = strcmp_null(fsopt1->mon_addr, fsopt2->mon_addr);\n	if (ret)\n		return ret;\n\n	return ceph_compare_options(new_opt, fsc->client);\n}\n\n/**\n * ceph_show_options - Show mount options in /proc/mounts\n * @m: seq_file to write to\n * @root: root of that (sub)tree\n */\nstatic int ceph_show_options(struct seq_file *m, struct dentry *root)\n{\n	struct ceph_fs_client *fsc = ceph_sb_to_fs_client(root->d_sb);\n	struct ceph_mount_options *fsopt = fsc->mount_options;\n	size_t pos;\n	int ret;\n\n	/* a comma between MNT/MS and client options */\n	seq_putc(m, ',');\n	pos = m->count;\n\n	ret = ceph_print_client_options(m, fsc->client, false);\n	if (ret)\n		return ret;\n\n	/* retract our comma if no client options */\n	if (m->count == pos)\n		m->count--;\n\n	if (fsopt->flags & CEPH_MOUNT_OPT_DIRSTAT)\n		seq_puts(m, \",dirstat\");\n	if ((fsopt->flags & CEPH_MOUNT_OPT_RBYTES))\n		seq_puts(m, \",rbytes\");\n	if (fsopt->flags & CEPH_MOUNT_OPT_NOASYNCREADDIR)\n		seq_puts(m, \",noasyncreaddir\");\n	if ((fsopt->flags & CEPH_MOUNT_OPT_DCACHE) == 0)\n		seq_puts(m, \",nodcache\");\n	if (fsopt->flags & CEPH_MOUNT_OPT_INO32)\n		seq_puts(m, \",ino32\");\n	if (fsopt->flags & CEPH_MOUNT_OPT_FSCACHE) {\n		seq_show_option(m, \"fsc\", fsopt->fscache_uniq);\n	}\n	if (fsopt->flags & CEPH_MOUNT_OPT_NOPOOLPERM)\n		seq_puts(m, \",nopoolperm\");\n	if (fsopt->flags & CEPH_MOUNT_OPT_NOQUOTADF)\n		seq_puts(m, \",noquotadf\");\n\n#ifdef CONFIG_CEPH_FS_POSIX_ACL\n	if (root->d_sb->s_flags & SB_POSIXACL)\n		seq_puts(m, \",acl\");\n	else\n		seq_puts(m, \",noacl\");\n#endif\n\n	if ((fsopt->flags & CEPH_MOUNT_OPT_NOCOPYFROM) == 0)\n		seq_puts(m, \",copyfrom\");\n\n	/* dump mds_namespace when old device syntax is in use */\n	if (fsopt->mds_namespace && !fsopt->new_dev_syntax)\n		seq_show_option(m, \"mds_namespace\", fsopt->mds_namespace);\n\n	if (fsopt->mon_addr)\n		seq_printf(m, \",mon_addr=%s\", fsopt->mon_addr);\n\n	if (fsopt->flags & CEPH_MOUNT_OPT_CLEANRECOVER)\n		seq_show_option(m, \"recover_session\", \"clean\");\n\n	if (!(fsopt->flags & CEPH_MOUNT_OPT_ASYNC_DIROPS))\n		seq_puts(m, \",wsync\");\n	if (fsopt->flags & CEPH_MOUNT_OPT_NOPAGECACHE)\n		seq_puts(m, \",nopagecache\");\n	if (fsopt->flags & CEPH_MOUNT_OPT_SPARSEREAD)\n		seq_puts(m, \",sparseread\");\n	if (fsopt->flags & CEPH_MOUNT_OPT_NEARFULL_SYNC)\n		seq_puts(m, \",nearfull_sync\");\n\n	fscrypt_show_test_dummy_encryption(m, ',', root->d_sb);\n\n	if (fsopt->wsize != CEPH_MAX_WRITE_SIZE)\n		seq_printf(m, \",wsize=%u\", fsopt->wsize);\n	if (fsopt->rsize != CEPH_MAX_READ_SIZE)\n		seq_printf(m, \",rsize=%u\", fsopt->rsize);\n	if (fsopt->rasize != CEPH_RASIZE_DEFAULT)\n		seq_printf(m, \",rasize=%u\", fsopt->rasize);\n	if (fsopt->congestion_kb != default_congestion_kb())\n		seq_printf(m, \",write_congestion_kb=%u\", fsopt->congestion_kb);\n	if (fsopt->caps_max)\n		seq_printf(m, \",caps_max=%d\", fsopt->caps_max);\n	if (fsopt->caps_wanted_delay_min != CEPH_CAPS_WANTED_DELAY_MIN_DEFAULT)\n		seq_printf(m, \",caps_wanted_delay_min=%u\",\n			 fsopt->caps_wanted_delay_min);\n	if (fsopt->caps_wanted_delay_max != CEPH_CAPS_WANTED_DELAY_MAX_DEFAULT)\n		seq_printf(m, \",caps_wanted_delay_max=%u\",\n			   fsopt->caps_wanted_delay_max);\n	if (fsopt->max_readdir != CEPH_MAX_READDIR_DEFAULT)\n		seq_printf(m, \",readdir_max_entries=%u\", fsopt->max_readdir);\n	if (fsopt->max_readdir_bytes != CEPH_MAX_READDIR_BYTES_DEFAULT)\n		seq_printf(m, \",readdir_max_bytes=%u\", fsopt->max_readdir_bytes);\n	if (strcmp(fsopt->snapdir_name, CEPH_SNAPDIRNAME_DEFAULT))\n		seq_show_option(m, \"snapdirname\", fsopt->snapdir_name);\n\n	return 0;\n}\n\n/*\n * handle any mon messages the standard library doesn't understand.\n * return error if we don't either.\n */\nstatic int extra_mon_dispatch(struct ceph_client *client, struct ceph_msg *msg)\n{\n	struct ceph_fs_client *fsc = client->private;\n	int type = le16_to_cpu(msg->hdr.type);\n\n	switch (type) {\n	case CEPH_MSG_MDS_MAP:\n		ceph_mdsc_handle_mdsmap(fsc->mdsc, msg);\n		return 0;\n	case CEPH_MSG_FS_MAP_USER:\n		ceph_mdsc_handle_fsmap(fsc->mdsc, msg);\n		return 0;\n	default:\n		return -1;\n	}\n}\n\n/*\n * create a new fs client\n *\n * Success or not, this function consumes @fsopt and @opt.\n */\nstatic struct ceph_fs_client *create_fs_client(struct ceph_mount_options *fsopt,\n					struct ceph_options *opt)\n{\n	struct ceph_fs_client *fsc;\n	int err;\n\n	fsc = kzalloc_obj(*fsc);\n	if (!fsc) {\n		err = -ENOMEM;\n		goto fail;\n	}\n\n	fsc->client = ceph_create_client(opt, fsc);\n	if (IS_ERR(fsc->client)) {\n		err = PTR_ERR(fsc->client);\n		goto fail;\n	}\n	opt = NULL; /* fsc->client now owns this */\n\n	fsc->client->extra_mon_dispatch = extra_mon_dispatch;\n	ceph_set_opt(fsc->client, ABORT_ON_FULL);\n\n	if (!fsopt->mds_namespace) {\n		ceph_monc_want_map(&fsc->client->monc, CEPH_SUB_MDSMAP,\n				   0, true);\n	} else {\n		ceph_monc_want_map(&fsc->client->monc, CEPH_SUB_FSMAP,\n				   0, false);\n	}\n\n	fsc->mount_options = fsopt;\n\n	fsc->sb = NULL;\n	fsc->mount_state = CEPH_MOUNT_MOUNTING;\n	fsc->filp_gen = 1;\n	fsc->have_copy_from2 = true;\n\n	atomic_long_set(&fsc->writeback_count, 0);\n	fsc->write_congested = false;\n\n	err = -ENOMEM;\n	/*\n	 * The number of concurrent works can be high but they don't need\n	 * to be processed in parallel, limit concurrency.\n	 */\n	fsc->inode_wq = alloc_workqueue(\"ceph-inode\", WQ_UNBOUND, 0);\n	if (!fsc->inode_wq)\n		goto fail_client;\n	fsc->cap_wq = alloc_workqueue(\"ceph-cap\", WQ_PERCPU, 1);\n	if (!fsc->cap_wq)\n		goto fail_inode_wq;\n\n	hash_init(fsc->async_unlink_conflict);\n	spin_lock_init(&fsc->async_unlink_conflict_lock);\n\n	spin_lock(&ceph_fsc_lock);\n	list_add_tail(&fsc->metric_wakeup, &ceph_fsc_list);\n	spin_unlock(&ceph_fsc_lock);\n\n	return fsc;\n\nfail_inode_wq:\n	destroy_workqueue(fsc->inode_wq);\nfail_client:\n	ceph_destroy_client(fsc->client);\nfail:\n	kfree(fsc);\n	if (opt)\n		ceph_destroy_options(opt);\n	destroy_mount_options(fsopt);\n	return ERR_PTR(err);\n}\n\nstatic void flush_fs_workqueues(struct ceph_fs_client *fsc)\n{\n	flush_workqueue(fsc->inode_wq);\n	flush_workqueue(fsc->cap_wq);\n}\n\nstatic void destroy_fs_client(struct ceph_fs_client *fsc)\n{\n	doutc(fsc->client, \"%p\\n\", fsc);\n\n	spin_lock(&ceph_fsc_lock);\n	list_del(&fsc->metric_wakeup);\n	spin_unlock(&ceph_fsc_lock);\n\n	ceph_mdsc_destroy(fsc);\n	destroy_workqueue(fsc->inode_wq);\n	destroy_workqueue(fsc->cap_wq);\n\n	destroy_mount_options(fsc->mount_options);\n\n	ceph_destroy_client(fsc->client);\n\n	kfree(fsc);\n	dout(\"%s: %p done\\n\", __func__, fsc);\n}\n\n/*\n * caches\n */\nstruct kmem_cache *ceph_inode_cachep;\nstruct kmem_cache *ceph_cap_cachep;\nstruct kmem_cache *ceph_cap_snap_cachep;\nstruct kmem_cache *ceph_cap_flush_cachep;\nstruct kmem_cache *ceph_dentry_cachep;\nstruct kmem_cache *ceph_file_cachep;\nstruct kmem_cache *ceph_dir_file_cachep;\nstruct kmem_cache *ceph_mds_request_cachep;\nmempool_t *ceph_wb_pagevec_pool;\n\nstatic void ceph_inode_init_once(void *foo)\n{\n	struct ceph_inode_info *ci = foo;\n	inode_init_once(&ci->netfs.inode);\n}\n\nstatic int __init init_caches(void)\n{\n	int error = -ENOMEM;\n\n	ceph_inode_cachep = kmem_cache_create(\"ceph_inode_info\",\n				      sizeof(struct ceph_inode_info),\n				      __alignof__(struct ceph_inode_info),\n				      SLAB_RECLAIM_ACCOUNT | SLAB_ACCOUNT,\n				      ceph_inode_init_once);\n	if (!ceph_inode_cachep)\n		return -ENOMEM;\n\n	ceph_cap_cachep = KMEM_CACHE(ceph_cap, 0);\n	if (!ceph_cap_cachep)\n		goto bad_cap;\n	ceph_cap_snap_cachep = KMEM_CACHE(ceph_cap_snap, 0);\n	if (!ceph_cap_snap_cachep)\n		goto bad_cap_snap;\n	ceph_cap_flush_cachep = KMEM_CACHE(ceph_cap_flush,\n					   SLAB_RECLAIM_ACCOUNT);\n	if (!ceph_cap_flush_cachep)\n		goto bad_cap_flush;\n\n	ceph_dentry_cachep = KMEM_CACHE(ceph_dentry_info,\n					SLAB_RECLAIM_ACCOUNT);\n	if (!ceph_dentry_cachep)\n		goto bad_dentry;\n\n	ceph_file_cachep = KMEM_CACHE(ceph_file_info, 0);\n	if (!ceph_file_cachep)\n		goto bad_file;\n\n	ceph_dir_file_cachep = KMEM_CACHE(ceph_dir_file_info, 0);\n	if (!ceph_dir_file_cachep)\n		goto bad_dir_file;\n\n	ceph_mds_request_cachep = KMEM_CACHE(ceph_mds_request, 0);\n	if (!ceph_mds_request_cachep)\n		goto bad_mds_req;\n\n	ceph_wb_pagevec_pool = mempool_create_kmalloc_pool(10,\n	    (CEPH_MAX_WRITE_SIZE >> PAGE_SHIFT) * sizeof(struct page *));\n	if (!ceph_wb_pagevec_pool)\n		goto bad_pagevec_pool;\n\n	error = ceph_subvolume_metrics_cache_init();\n	if (error)\n		goto bad_subvol_metrics;\n\n	return 0;\n\nbad_subvol_metrics:\n	mempool_destroy(ceph_wb_pagevec_pool);\nbad_pagevec_pool:\n	kmem_cache_destroy(ceph_mds_request_cachep);\nbad_mds_req:\n	kmem_cache_destroy(ceph_dir_file_cachep);\nbad_dir_file:\n	kmem_cache_destroy(ceph_file_cachep);\nbad_file:\n	kmem_cache_destroy(ceph_dentry_cachep);\nbad_dentry:\n	kmem_cache_destroy(ceph_cap_flush_cachep);\nbad_cap_flush:\n	kmem_cache_destroy(ceph_cap_snap_cachep);\nbad_cap_snap:\n	kmem_cache_destroy(ceph_cap_cachep);\nbad_cap:\n	kmem_cache_destroy(ceph_inode_cachep);\n	return error;\n}\n\nstatic void destroy_caches(void)\n{\n	/*\n	 * Make sure all delayed rcu free inodes are flushed before we\n	 * destroy cache.\n	 */\n	rcu_barrier();\n\n	kmem_cache_destroy(ceph_inode_cachep);\n	kmem_cache_destroy(ceph_cap_cachep);\n	kmem_cache_destroy(ceph_cap_snap_cachep);\n	kmem_cache_destroy(ceph_cap_flush_cachep);\n	kmem_cache_destroy(ceph_dentry_cachep);\n	kmem_cache_destroy(ceph_file_cachep);\n	kmem_cache_destroy(ceph_dir_file_cachep);\n	kmem_cache_destroy(ceph_mds_request_cachep);\n	mempool_destroy(ceph_wb_pagevec_pool);\n	ceph_subvolume_metrics_cache_destroy();\n}\n\nstatic void __ceph_umount_begin(struct ceph_fs_client *fsc)\n{\n	ceph_osdc_abort_requests(&fsc->client->osdc, -EIO);\n	ceph_mdsc_force_umount(fsc->mdsc);\n	fsc->filp_gen++; // invalidate open files\n}\n\n/*\n * ceph_umount_begin - initiate forced umount.  Tear down the\n * mount, skipping steps that may hang while waiting for server(s).\n */\nvoid ceph_umount_begin(struct super_block *sb)\n{\n	struct ceph_fs_client *fsc = ceph_sb_to_fs_client(sb);\n\n	doutc(fsc->client, \"starting forced umount\\n\");\n\n	fsc->mount_state = CEPH_MOUNT_SHUTDOWN;\n	__ceph_umount_begin(fsc);\n}\n\nstatic const struct super_operations ceph_super_ops = {\n	.alloc_inode	= ceph_alloc_inode,\n	.free_inode	= ceph_free_inode,\n	.write_inode    = ceph_write_inode,\n	.drop_inode	= inode_just_drop,\n	.evict_inode	= ceph_evict_inode,\n	.sync_fs        = ceph_sync_fs,\n	.put_super	= ceph_put_super,\n	.show_options   = ceph_show_options,\n	.statfs		= ceph_statfs,\n	.umount_begin   = ceph_umount_begin,\n};\n\n/*\n * Bootstrap mount by opening the root directory.  Note the mount\n * @started time from caller, and time out if this takes too long.\n */\nstatic struct dentry *open_root_dentry(struct ceph_fs_client *fsc,\n				       const char *path,\n				       unsigned long started)\n{\n	struct ceph_client *cl = fsc->client;\n	struct ceph_mds_client *mdsc = fsc->mdsc;\n	struct ceph_mds_request *req = NULL;\n	int err;\n	struct dentry *root;\n\n	/* open dir */\n	doutc(cl, \"opening '%s'\\n\", path);\n	req = ceph_mdsc_create_request(mdsc, CEPH_MDS_OP_GETATTR, USE_ANY_MDS);\n	if (IS_ERR(req))\n		return ERR_CAST(req);\n	req->r_path1 = kstrdup(path, GFP_NOFS);\n	if (!req->r_path1) {\n		root = ERR_PTR(-ENOMEM);\n		goto out;\n	}\n\n	req->r_ino1.ino = CEPH_INO_ROOT;\n	req->r_ino1.snap = CEPH_NOSNAP;\n	req->r_started = started;\n	req->r_timeout = fsc->client->options->mount_timeout;\n	req->r_args.getattr.mask = cpu_to_le32(CEPH_STAT_CAP_INODE);\n	req->r_num_caps = 2;\n	err = ceph_mdsc_do_request(mdsc, NULL, req);\n	if (err == 0) {\n		struct inode *inode = req->r_target_inode;\n		req->r_target_inode = NULL;\n		doutc(cl, \"success\\n\");\n		root = d_make_root(inode);\n		if (!root) {\n			root = ERR_PTR(-ENOMEM);\n			goto out;\n		}\n		doutc(cl, \"success, root dentry is %p\\n\", root);\n	} else {\n		root = ERR_PTR(err);\n	}\nout:\n	ceph_mdsc_put_request(req);\n	return root;\n}\n\n#ifdef CONFIG_FS_ENCRYPTION\nstatic int ceph_apply_test_dummy_encryption(struct super_block *sb,\n					    struct fs_context *fc,\n					    struct ceph_mount_options *fsopt)\n{\n	struct ceph_fs_client *fsc = sb->s_fs_info;\n\n	if (!fscrypt_is_dummy_policy_set(&fsopt->dummy_enc_policy))\n		return 0;\n\n	/* No changing encryption context on remount. */\n	if (fc->purpose == FS_CONTEXT_FOR_RECONFIGURE &&\n	    !fscrypt_is_dummy_policy_set(&fsc->fsc_dummy_enc_policy)) {\n		if (fscrypt_dummy_policies_equal(&fsopt->dummy_enc_policy,\n						 &fsc->fsc_dummy_enc_policy))\n			return 0;\n		errorfc(fc, \"Can't set test_dummy_encryption on remount\");\n		return -EINVAL;\n	}\n\n	/* Also make sure fsopt doesn't contain a conflicting value. */\n	if (fscrypt_is_dummy_policy_set(&fsc->fsc_dummy_enc_policy)) {\n		if (fscrypt_dummy_policies_equal(&fsopt->dummy_enc_policy,\n						 &fsc->fsc_dummy_enc_policy))\n			return 0;\n		errorfc(fc, \"Conflicting test_dummy_encryption options\");\n		return -EINVAL;\n	}\n\n	fsc->fsc_dummy_enc_policy = fsopt->dummy_enc_policy;\n	memset(&fsopt->dummy_enc_policy, 0, sizeof(fsopt->dummy_enc_policy));\n\n	warnfc(fc, \"test_dummy_encryption mode enabled\");\n	return 0;\n}\n#else\nstatic int ceph_apply_test_dummy_encryption(struct super_block *sb,\n					    struct fs_context *fc,\n					    struct ceph_mount_options *fsopt)\n{\n	return 0;\n}\n#endif\n\n/*\n * mount: join the ceph cluster, and open root directory.\n */\nstatic struct dentry *ceph_real_mount(struct ceph_fs_client *fsc,\n				      struct fs_context *fc)\n{\n	struct ceph_client *cl = fsc->client;\n	int err;\n	unsigned long started = jiffies;  /* note the start time */\n	struct dentry *root;\n\n	doutc(cl, \"mount start %p\\n\", fsc);\n	mutex_lock(&fsc->client->mount_mutex);\n\n	if (!fsc->sb->s_root) {\n		const char *path = fsc->mount_options->server_path ?\n				     fsc->mount_options->server_path + 1 : \"\";\n\n		err = __ceph_open_session(fsc->client);\n		if (err < 0)\n			goto out;\n\n		/* setup fscache */\n		if (fsc->mount_options->flags & CEPH_MOUNT_OPT_FSCACHE) {\n			err = ceph_fscache_register_fs(fsc, fc);\n			if (err < 0)\n				goto out;\n		}\n\n		err = ceph_apply_test_dummy_encryption(fsc->sb, fc,\n						       fsc->mount_options);\n		if (err)\n			goto out;\n\n		doutc(cl, \"mount opening path '%s'\\n\", path);\n\n		ceph_fs_debugfs_init(fsc);\n\n		root = open_root_dentry(fsc, path, started);\n		if (IS_ERR(root)) {\n			err = PTR_ERR(root);\n			goto out;\n		}\n		fsc->sb->s_root = dget(root);\n	} else {\n		root = dget(fsc->sb->s_root);\n	}\n\n	fsc->mount_state = CEPH_MOUNT_MOUNTED;\n	doutc(cl, \"mount success\\n\");\n	mutex_unlock(&fsc->client->mount_mutex);\n	return root;\n\nout:\n	mutex_unlock(&fsc->client->mount_mutex);\n	ceph_fscrypt_free_dummy_policy(fsc);\n	return ERR_PTR(err);\n}\n\nstatic int ceph_set_super(struct super_block *s, struct fs_context *fc)\n{\n	struct ceph_fs_client *fsc = s->s_fs_info;\n	struct ceph_client *cl = fsc->client;\n	int ret;\n\n	doutc(cl, \"%p\\n\", s);\n\n	s->s_maxbytes = MAX_LFS_FILESIZE;\n\n	s->s_xattr = ceph_xattr_handlers;\n	fsc->sb = s;\n	fsc->max_file_size = 1ULL << 40; /* temp value until we get mdsmap */\n\n	s->s_op = &ceph_super_ops;\n	set_default_d_op(s, &ceph_dentry_ops);\n	s->s_export_op = &ceph_export_ops;\n\n	s->s_time_gran = 1;\n	s->s_time_min = 0;\n	s->s_time_max = U32_MAX;\n	s->s_flags |= SB_NODIRATIME | SB_NOATIME;\n	s->s_magic = CEPH_SUPER_MAGIC;\n\n	ceph_fscrypt_set_ops(s);\n\n	ret = set_anon_super_fc(s, fc);\n	if (ret != 0)\n		fsc->sb = NULL;\n	return ret;\n}\n\n/*\n * share superblock if same fs AND options\n */\nstatic int ceph_compare_super(struct super_block *sb, struct fs_context *fc)\n{\n	struct ceph_fs_client *new = fc->s_fs_info;\n	struct ceph_mount_options *fsopt = new->mount_options;\n	struct ceph_options *opt = new->client->options;\n	struct ceph_fs_client *fsc = ceph_sb_to_fs_client(sb);\n	struct ceph_client *cl = fsc->client;\n\n	doutc(cl, \"%p\\n\", sb);\n\n	if (compare_mount_options(fsopt, opt, fsc)) {\n		doutc(cl, \"monitor(s)/mount options don't match\\n\");\n		return 0;\n	}\n	if ((opt->flags & CEPH_OPT_FSID) &&\n	    ceph_fsid_compare(&opt->fsid, &fsc->client->fsid)) {\n		doutc(cl, \"fsid doesn't match\\n\");\n		return 0;\n	}\n	if (fc->sb_flags != (sb->s_flags & ~SB_BORN)) {\n		doutc(cl, \"flags differ\\n\");\n		return 0;\n	}\n\n	if (fsc->blocklisted && !ceph_test_mount_opt(fsc, CLEANRECOVER)) {\n		doutc(cl, \"client is blocklisted (and CLEANRECOVER is not set)\\n\");\n		return 0;\n	}\n\n	if (fsc->mount_state == CEPH_MOUNT_SHUTDOWN) {\n		doutc(cl, \"client has been forcibly unmounted\\n\");\n		return 0;\n	}\n\n	return 1;\n}\n\n/*\n * construct our own bdi so we can control readahead, etc.\n */\nstatic atomic_long_t bdi_seq = ATOMIC_LONG_INIT(0);\n\nstatic int ceph_setup_bdi(struct super_block *sb, struct ceph_fs_client *fsc)\n{\n	int err;\n\n	err = super_setup_bdi_name(sb, \"ceph-%ld\",\n				   atomic_long_inc_return(&bdi_seq));\n	if (err)\n		return err;\n\n	/* set ra_pages based on rasize mount option? */\n	sb->s_bdi->ra_pages = fsc->mount_options->rasize >> PAGE_SHIFT;\n\n	/* set io_pages based on max osd read size */\n	sb->s_bdi->io_pages = fsc->mount_options->rsize >> PAGE_SHIFT;\n\n	return 0;\n}\n\nstatic int ceph_get_tree(struct fs_context *fc)\n{\n	struct ceph_parse_opts_ctx *pctx = fc->fs_private;\n	struct ceph_mount_options *fsopt = pctx->opts;\n	struct super_block *sb;\n	struct ceph_fs_client *fsc;\n	struct dentry *res;\n	int (*compare_super)(struct super_block *, struct fs_context *) =\n		ceph_compare_super;\n	int err;\n\n	dout(\"ceph_get_tree\\n\");\n\n	if (!fc->source)\n		return invalfc(fc, \"No source\");\n	if (fsopt->new_dev_syntax && !fsopt->mon_addr)\n		return invalfc(fc, \"No monitor address\");\n\n	/* create client (which we may/may not use) */\n	fsc = create_fs_client(pctx->opts, pctx->copts);\n	pctx->opts = NULL;\n	pctx->copts = NULL;\n	if (IS_ERR(fsc)) {\n		err = PTR_ERR(fsc);\n		goto out_final;\n	}\n\n	err = ceph_mdsc_init(fsc);\n	if (err < 0)\n		goto out;\n\n	if (ceph_test_opt(fsc->client, NOSHARE))\n		compare_super = NULL;\n\n	fc->s_fs_info = fsc;\n	sb = sget_fc(fc, compare_super, ceph_set_super);\n	fc->s_fs_info = NULL;\n	if (IS_ERR(sb)) {\n		err = PTR_ERR(sb);\n		goto out;\n	}\n\n	if (ceph_sb_to_fs_client(sb) != fsc) {\n		destroy_fs_client(fsc);\n		fsc = ceph_sb_to_fs_client(sb);\n		dout(\"get_sb got existing client %p\\n\", fsc);\n	} else {\n		dout(\"get_sb using new client %p\\n\", fsc);\n		err = ceph_setup_bdi(sb, fsc);\n		if (err < 0)\n			goto out_splat;\n	}\n\n	res = ceph_real_mount(fsc, fc);\n	if (IS_ERR(res)) {\n		err = PTR_ERR(res);\n		goto out_splat;\n	}\n\n	doutc(fsc->client, \"root %p inode %p ino %llx.%llx\\n\", res,\n		    d_inode(res), ceph_vinop(d_inode(res)));\n	fc->root = fsc->sb->s_root;\n	return 0;\n\nout_splat:\n	if (!ceph_mdsmap_is_cluster_available(fsc->mdsc->mdsmap)) {\n		pr_info(\"No mds server is up or the cluster is laggy\\n\");\n		err = -EHOSTUNREACH;\n	}\n\n	ceph_mdsc_close_sessions(fsc->mdsc);\n	deactivate_locked_super(sb);\n	goto out_final;\n\nout:\n	destroy_fs_client(fsc);\nout_final:\n	dout(\"ceph_get_tree fail %d\\n\", err);\n	return err;\n}\n\nstatic void ceph_free_fc(struct fs_context *fc)\n{\n	struct ceph_parse_opts_ctx *pctx = fc->fs_private;\n\n	if (pctx) {\n		destroy_mount_options(pctx->opts);\n		ceph_destroy_options(pctx->copts);\n		kfree(pctx);\n	}\n}\n\nstatic int ceph_reconfigure_fc(struct fs_context *fc)\n{\n	int err;\n	struct ceph_parse_opts_ctx *pctx = fc->fs_private;\n	struct ceph_mount_options *fsopt = pctx->opts;\n	struct super_block *sb = fc->root->d_sb;\n	struct ceph_fs_client *fsc = ceph_sb_to_fs_client(sb);\n\n	err = ceph_apply_test_dummy_encryption(sb, fc, fsopt);\n	if (err)\n		return err;\n\n	if (fsopt->flags & CEPH_MOUNT_OPT_ASYNC_DIROPS)\n		ceph_set_mount_opt(fsc, ASYNC_DIROPS);\n	else\n		ceph_clear_mount_opt(fsc, ASYNC_DIROPS);\n\n	if (fsopt->flags & CEPH_MOUNT_OPT_SPARSEREAD)\n		ceph_set_mount_opt(fsc, SPARSEREAD);\n	else\n		ceph_clear_mount_opt(fsc, SPARSEREAD);\n\n	if (strcmp_null(fsc->mount_options->mon_addr, fsopt->mon_addr)) {\n		kfree(fsc->mount_options->mon_addr);\n		fsc->mount_options->mon_addr = fsopt->mon_addr;\n		fsopt->mon_addr = NULL;\n		pr_notice_client(fsc->client,\n			\"monitor addresses recorded, but not used for reconnection\");\n	}\n\n	sync_filesystem(sb);\n	return 0;\n}\n\nstatic const struct fs_context_operations ceph_context_ops = {\n	.free		= ceph_free_fc,\n	.parse_param	= ceph_parse_mount_param,\n	.get_tree	= ceph_get_tree,\n	.reconfigure	= ceph_reconfigure_fc,\n};\n\n/*\n * Set up the filesystem mount context.\n */\nstatic int ceph_init_fs_context(struct fs_context *fc)\n{\n	struct ceph_parse_opts_ctx *pctx;\n	struct ceph_mount_options *fsopt;\n\n	pctx = kzalloc_obj(*pctx);\n	if (!pctx)\n		return -ENOMEM;\n\n	pctx->copts = ceph_alloc_options();\n	if (!pctx->copts)\n		goto nomem;\n\n	pctx->opts = kzalloc_obj(*pctx->opts);\n	if (!pctx->opts)\n		goto nomem;\n\n	fsopt = pctx->opts;\n	fsopt->flags = CEPH_MOUNT_OPT_DEFAULT;\n\n	fsopt->wsize = CEPH_MAX_WRITE_SIZE;\n	fsopt->rsize = CEPH_MAX_READ_SIZE;\n	fsopt->rasize = CEPH_RASIZE_DEFAULT;\n	fsopt->snapdir_name = kstrdup(CEPH_SNAPDIRNAME_DEFAULT, GFP_KERNEL);\n	if (!fsopt->snapdir_name)\n		goto nomem;\n\n	fsopt->caps_wanted_delay_min = CEPH_CAPS_WANTED_DELAY_MIN_DEFAULT;\n	fsopt->caps_wanted_delay_max = CEPH_CAPS_WANTED_DELAY_MAX_DEFAULT;\n	fsopt->max_readdir = CEPH_MAX_READDIR_DEFAULT;\n	fsopt->max_readdir_bytes = CEPH_MAX_READDIR_BYTES_DEFAULT;\n	fsopt->congestion_kb = default_congestion_kb();\n\n#ifdef CONFIG_CEPH_FS_POSIX_ACL\n	fc->sb_flags |= SB_POSIXACL;\n#endif\n\n	fc->fs_private = pctx;\n	fc->ops = &ceph_context_ops;\n	return 0;\n\nnomem:\n	destroy_mount_options(pctx->opts);\n	ceph_destroy_options(pctx->copts);\n	kfree(pctx);\n	return -ENOMEM;\n}\n\n/*\n * Return true if it successfully increases the blocker counter,\n * or false if the mdsc is in stopping and flushed state.\n */\nstatic bool __inc_stopping_blocker(struct ceph_mds_client *mdsc)\n{\n	spin_lock(&mdsc->stopping_lock);\n	if (mdsc->stopping >= CEPH_MDSC_STOPPING_FLUSHING) {\n		spin_unlock(&mdsc->stopping_lock);\n		return false;\n	}\n	atomic_inc(&mdsc->stopping_blockers);\n	spin_unlock(&mdsc->stopping_lock);\n	return true;\n}\n\nstatic void __dec_stopping_blocker(struct ceph_mds_client *mdsc)\n{\n	spin_lock(&mdsc->stopping_lock);\n	if (!atomic_dec_return(&mdsc->stopping_blockers) &&\n	    mdsc->stopping >= CEPH_MDSC_STOPPING_FLUSHING)\n		complete_all(&mdsc->stopping_waiter);\n	spin_unlock(&mdsc->stopping_lock);\n}\n\n/* For metadata IO requests */\nbool ceph_inc_mds_stopping_blocker(struct ceph_mds_client *mdsc,\n				   struct ceph_mds_session *session)\n{\n	mutex_lock(&session->s_mutex);\n	inc_session_sequence(session);\n	mutex_unlock(&session->s_mutex);\n\n	return __inc_stopping_blocker(mdsc);\n}\n\nvoid ceph_dec_mds_stopping_blocker(struct ceph_mds_client *mdsc)\n{\n	__dec_stopping_blocker(mdsc);\n}\n\n/* For data IO requests */\nbool ceph_inc_osd_stopping_blocker(struct ceph_mds_client *mdsc)\n{\n	return __inc_stopping_blocker(mdsc);\n}\n\nvoid ceph_dec_osd_stopping_blocker(struct ceph_mds_client *mdsc)\n{\n	__dec_stopping_blocker(mdsc);\n}\n\nstatic void ceph_kill_sb(struct super_block *s)\n{\n	struct ceph_fs_client *fsc = ceph_sb_to_fs_client(s);\n	struct ceph_client *cl = fsc->client;\n	struct ceph_mds_client *mdsc = fsc->mdsc;\n	bool wait;\n\n	doutc(cl, \"%p\\n\", s);\n\n	ceph_mdsc_pre_umount(mdsc);\n	flush_fs_workqueues(fsc);\n\n	/*\n	 * Though the kill_anon_super() will finally trigger the\n	 * sync_filesystem() anyway, we still need to do it here and\n	 * then bump the stage of shutdown. This will allow us to\n	 * drop any further message, which will increase the inodes'\n	 * i_count reference counters but makes no sense any more,\n	 * from MDSs.\n	 *\n	 * Without this when evicting the inodes it may fail in the\n	 * kill_anon_super(), which will trigger a warning when\n	 * destroying the fscrypt keyring and then possibly trigger\n	 * a further crash in ceph module when the iput() tries to\n	 * evict the inodes later.\n	 */\n	sync_filesystem(s);\n\n	if (atomic64_read(&mdsc->dirty_folios) > 0) {\n		wait_queue_head_t *wq = &mdsc->flush_end_wq;\n		long timeleft = wait_event_killable_timeout(*wq,\n					atomic64_read(&mdsc->dirty_folios) <= 0,\n					fsc->client->options->mount_timeout);\n		if (!timeleft) /* timed out */\n			pr_warn_client(cl, \"umount timed out, %ld\\n\", timeleft);\n		else if (timeleft < 0) /* killed */\n			pr_warn_client(cl, \"umount was killed, %ld\\n\", timeleft);\n	}\n\n	spin_lock(&mdsc->stopping_lock);\n	mdsc->stopping = CEPH_MDSC_STOPPING_FLUSHING;\n	wait = !!atomic_read(&mdsc->stopping_blockers);\n	spin_unlock(&mdsc->stopping_lock);\n\n	if (wait && atomic_read(&mdsc->stopping_blockers)) {\n		long timeleft = wait_for_completion_killable_timeout(\n					&mdsc->stopping_waiter,\n					fsc->client->options->mount_timeout);\n		if (!timeleft) /* timed out */\n			pr_warn_client(cl, \"umount timed out, %ld\\n\", timeleft);\n		else if (timeleft < 0) /* killed */\n			pr_warn_client(cl, \"umount was killed, %ld\\n\", timeleft);\n	}\n\n	mdsc->stopping = CEPH_MDSC_STOPPING_FLUSHED;\n	kill_anon_super(s);\n\n	fsc->client->extra_mon_dispatch = NULL;\n	ceph_fs_debugfs_cleanup(fsc);\n\n	ceph_fscache_unregister_fs(fsc);\n\n	destroy_fs_client(fsc);\n}\n\nstatic struct file_system_type ceph_fs_type = {\n	.owner		= THIS_MODULE,\n	.name		= \"ceph\",\n	.init_fs_context = ceph_init_fs_context,\n	.kill_sb	= ceph_kill_sb,\n	.fs_flags	= FS_RENAME_DOES_D_MOVE | FS_ALLOW_IDMAP,\n};\nMODULE_ALIAS_FS(\"ceph\");\n\nint ceph_force_reconnect(struct super_block *sb)\n{\n	struct ceph_fs_client *fsc = ceph_sb_to_fs_client(sb);\n	int err = 0;\n\n	fsc->mount_state = CEPH_MOUNT_RECOVER;\n	__ceph_umount_begin(fsc);\n\n	/* Make sure all page caches get invalidated.\n	 * see remove_session_caps_cb() */\n	flush_workqueue(fsc->inode_wq);\n\n	/* In case that we were blocklisted. This also reset\n	 * all mon/osd connections */\n	ceph_reset_client_addr(fsc->client);\n\n	ceph_osdc_clear_abort_err(&fsc->client->osdc);\n\n	fsc->blocklisted = false;\n	fsc->mount_state = CEPH_MOUNT_MOUNTED;\n\n	if (sb->s_root) {\n		err = __ceph_do_getattr(d_inode(sb->s_root), NULL,\n					CEPH_STAT_CAP_INODE, true);\n	}\n	return err;\n}\n\nstatic int __init init_ceph(void)\n{\n	int ret = init_caches();\n	if (ret)\n		goto out;\n\n	ceph_flock_init();\n	ret = register_filesystem(&ceph_fs_type);\n	if (ret)\n		goto out_caches;\n\n	pr_info(\"loaded (mds proto %d)\\n\", CEPH_MDSC_PROTOCOL);\n\n	return 0;\n\nout_caches:\n	destroy_caches();\nout:\n	return ret;\n}\n\nstatic void __exit exit_ceph(void)\n{\n	dout(\"exit_ceph\\n\");\n	unregister_filesystem(&ceph_fs_type);\n	destroy_caches();\n}\n\nstatic int param_set_metrics(const char *val, const struct kernel_param *kp)\n{\n	struct ceph_fs_client *fsc;\n	int ret;\n\n	ret = param_set_bool(val, kp);\n	if (ret) {\n		pr_err(\"Failed to parse sending metrics switch value '%s'\\n\",\n		       val);\n		return ret;\n	} else if (!disable_send_metrics) {\n		// wake up all the mds clients\n		spin_lock(&ceph_fsc_lock);\n		list_for_each_entry(fsc, &ceph_fsc_list, metric_wakeup) {\n			metric_schedule_delayed(&fsc->mdsc->metric);\n		}\n		spin_unlock(&ceph_fsc_lock);\n	}\n\n	return 0;\n}\n\nstatic const struct kernel_param_ops param_ops_metrics = {\n	.set = param_set_metrics,\n	.get = param_get_bool,\n};\n\nbool disable_send_metrics = false;\nmodule_param_cb(disable_send_metrics, &param_ops_metrics, &disable_send_metrics, 0644);\nMODULE_PARM_DESC(disable_send_metrics, \"Enable sending perf metrics to ceph cluster (default: on)\");\n\n/* for both v1 and v2 syntax */\nstatic bool mount_support = true;\nstatic const struct kernel_param_ops param_ops_mount_syntax = {\n	.get = param_get_bool,\n};\nmodule_param_cb(mount_syntax_v1, &param_ops_mount_syntax, &mount_support, 0444);\nmodule_param_cb(mount_syntax_v2, &param_ops_mount_syntax, &mount_support, 0444);\n\nbool enable_unsafe_idmap = false;\nmodule_param(enable_unsafe_idmap, bool, 0644);\nMODULE_PARM_DESC(enable_unsafe_idmap,\n		 \"Allow to use idmapped mounts with MDS without CEPHFS_FEATURE_HAS_OWNER_UIDGID\");\n\nmodule_init(init_ceph);\nmodule_exit(exit_ceph);\n\nMODULE_AUTHOR(\"Sage Weil <sage@newdream.net>\");\nMODULE_AUTHOR(\"Yehuda Sadeh <yehuda@hq.newdream.net>\");\nMODULE_AUTHOR(\"Patience Warnick <patience@newdream.net>\");\nMODULE_DESCRIPTION(\"Ceph filesystem for Linux\");\nMODULE_LICENSE(\"GPL\");\n";

